        foreach ($gazaNames as $id => $data) {
            $subscribers[] = [
                'id' => $id,
                'subscription_number' => '012010' . str_pad($id, 3, '0', STR_PAD_LEFT),
                'subscriber_id_number' => $data[0],
                'subscriber_name' => $data[1],
                'phone' => $data[2],
                'governorate_name' => '20', // غزة
                'address' => $data[3],
                'subscription_date' => '2026-02-21',
                'subscription_category' => 1,
                'phase_type' => 1,
                'subscription_status' => 1,
                'meter_number' => $data[4],
