                'opening_reading' => null,
                'service_type' => 1,
                'is_employee_subscription' => 0,
                'created_by' => 9,
                'last_updated_by' => 9,
            ];
        }

        $now = now();

        foreach ($subscribers as $sub) {
            DB::table('subscribers')->updateOrInsert(
                ['id' => $sub['id']],
                array_merge($sub, [
                    'created_at' => $now,
                    'updated_at' => $now,
                ])
            );
        }

        // ربط المشتركين بوحدات التوليد
        // مشتركين 1-259 = وحدة توليد 1, مشتركين 260-262 = وحدة توليد 2
        foreach ($subscribers as $sub) {
            $unitId = $sub['id'] >= 260 ? 2 : 1;
            DB::table('subscriber_generation_unit')->updateOrInsert(
                ['subscriber_id' => $sub['id'], 'generation_unit_id' => $unitId],
                ['created_at' => $now, 'updated_at' => $now]
            );
        }

        $this->command->info('تم إدراج/تحديث ' . count($subscribers) . ' مشترك + ربط وحدات التوليد بنجاح.');
